def attackers_of(f,r):
    """list of (asq, mid_nc, acls) : black attackers of square (f,r)"""
    sq=idx(f,r); out=[]
    for df,dr in KN:
        tf,tr=f+df,r+dr
        if inb(tf,tr):
            a=idx(tf,tr); out.append((a,fmid_nc(min(sq,a),max(sq,a)),'n'))
    for df,dr in KG:
        tf,tr=f+df,r+dr
        if inb(tf,tr):
            a=idx(tf,tr); out.append((a,fmid_nc(min(sq,a),max(sq,a)),'k'))
    for df in (-1,1):
        tf,tr=f+df,r+1
        if inb(tf,tr):
            a=idx(tf,tr); out.append((a,fmid_nc(min(sq,a),max(sq,a)),'p'))
    for df,dr in DIRS_R:
        stride=abs(df-8*dr); tf,tr=f,r
        for d in range(1,8):
            tf+=df; tr+=dr
            if not inb(tf,tr): break
            a=idx(tf,tr); out.append((a,smid_nc(min(sq,a),max(sq,a),stride),'[rq]'))
    for df,dr in DIRS_B:
        stride=abs(df-8*dr); tf,tr=f,r
        for d in range(1,8):
            tf+=df; tr+=dr
            if not inb(tf,tr): break
            a=idx(tf,tr); out.append((a,smid_nc(min(sq,a),max(sq,a),stride),'[bq]'))
    return out

def attack_alts(sq):
    f,r=sq%8,8-(sq//8); alts=[]
    for a,mid,acls in attackers_of(f,r):
        if sq<a: alts.append('.{%d}.'%sq+mid+acls)
        else: alts.append('.{%d}'%a+acls+mid+'.')
    return '(?:'+'|'.join(alts)+')'

